import Foundation

// Kikaron Multipass: "Log in with Kikaron". Generated by kikaron/brand.sh.

/// The Kikaron sign-in opens by itself when the app STARTS without an account
/// (armed by the start route, not after a log-out, never in an extension); after
/// a cancel or an error the fallback screen's button is the way back in.
@MainActor
enum KikaronAutoSignIn {
    static var pending = false
}

enum KikaronStrings {
    private static var language: String {
        Bundle.main.preferredLocalizations.first.map { String($0.prefix(2)) } ?? "en"
    }

    static var logInWithKikaron: String {
        switch language {
        case "nl": "Inloggen met Kikaron"
        case "de": "Mit Kikaron anmelden"
        case "fr": "Se connecter avec Kikaron"
        default: "Log in with Kikaron"
        }
    }

    static var unlockHint: String {
        switch language {
        case "nl": "Voer uw Multipass-wachtwoord in om uw kluis te openen."
        case "de": "Geben Sie Ihr Multipass-Passwort ein, um Ihren Tresor zu öffnen."
        case "fr": "Saisissez votre mot de passe Multipass pour ouvrir votre coffre."
        default: "Enter your Multipass password to open your vault."
        }
    }

    static var unlockHintPIN: String {
        switch language {
        case "nl": "Voer uw pincode in om uw kluis te openen."
        case "de": "Geben Sie Ihre PIN ein, um Ihren Tresor zu öffnen."
        case "fr": "Saisissez votre code PIN pour ouvrir votre coffre."
        default: "Enter your PIN to open your vault."
        }
    }

    static var multipassPassword: String {
        switch language {
        case "nl": "Multipass-wachtwoord"
        case "de": "Multipass-Passwort"
        case "fr": "Mot de passe Multipass"
        default: "Multipass password"
        }
    }

    static var unlock: String {
        switch language {
        case "nl": "Ontgrendel"
        case "de": "Entsperren"
        case "fr": "Déverrouiller"
        default: "Unlock"
        }
    }

    static var logInWithEmail: String {
        switch language {
        case "nl": "Inloggen met e-mail en hoofdwachtwoord"
        case "de": "Mit E-Mail und Master-Passwort anmelden"
        case "fr": "Se connecter avec e-mail et mot de passe principal"
        default: "Log in with email and master password"
        }
    }
}
